* Main Selection Menu - role-based category launcher
MAP MYMENU SIZE 24x80
  FIELD AT 1,1  LEN 6  PROT BRIGHT COLOR=GREEN  "MYIF01"
  FIELD AT 1,25 LEN 30 PROT BRIGHT COLOR=GREEN  "BRICKS SELECTION MENU"
  INPUT DATFLD  AT 1,65 LEN 10 PROT COLOR=GREEN
  STOP          AT 1,75
  FIELD AT 2,1  LEN 8  PROT COLOR=GREEN         "MYMENU00"
  INPUT USRFLD  AT 2,28 LEN 8  PROT COLOR=GREEN
  STOP          AT 2,36
  INPUT TIMFLD  AT 2,65 LEN 8  PROT COLOR=GREEN
  STOP          AT 2,73

  FIELD AT 4,3  LEN 38 PROT COLOR=TURQUOISE  "01.  REXX PROGRAMS"
  FIELD AT 5,3  LEN 38 PROT COLOR=TURQUOISE  "02.  COBOL PROGRAMS"
  FIELD AT 6,3  LEN 38 PROT COLOR=TURQUOISE  "03.  CUSTOMER MANAGEMENT"
  FIELD AT 7,3  LEN 38 PROT COLOR=TURQUOISE  "04.  QUEUE AND STORAGE"
  FIELD AT 8,3  LEN 38 PROT COLOR=TURQUOISE  "05.  SQL / DATABASE"
  FIELD AT 9,3  LEN 38 PROT COLOR=TURQUOISE  "06.  SYSTEM AND ADMIN"
  FIELD AT 11,3 LEN 38 PROT COLOR=TURQUOISE  "07.  LOGOFF"

  INPUT ROLEFLD AT 21,40 LEN 20 PROT COLOR=GREEN
  STOP          AT 21,60
  FIELD AT 21,3  LEN 12 PROT COLOR=GREEN     "SELECTION =>"
  INPUT SELFLD   AT 21,16 LEN 2 UNPROT COLOR=GREEN
  STOP           AT 21,19

  FIELD AT 23,1 LEN 78 PROT COLOR=GREEN  "PF:  1 LOGOFF                                  7 BWD   8 FWD"
  CURSOR AT SELFLD
ENDMAP
